mapper.select:
SELECT count(*)
FROM tb_screen_reagent
WHERE name = #{name}
  AND type = #{type}
  AND reagent_specs_num = #{reagentSpecsNum}
  AND titer = #{titer}
  AND potency_unit = #{potencyUnit}
  AND specification = #{specification}
  AND specification_unit = #{specificationUnit}
  AND package_unit = #{packageUnit}
  AND manufacturer = #{manufacturer}
  AND threshold = #{threshold}
  AND deleted = 0
